/* @DBAnnotatedObjectInfo(version = 0) */
public class DBTraceSnapshot : DBAnnotatedObject, TraceSnapshot {
	protected static readonly string TABLE_NAME = "Snapshots";

	protected static readonly string REAL_TIME_COLUMN_NAME = "RealTime";
	protected static readonly string SCHEDULE_COLUMN_NAME = "Schedule";
	protected static readonly string VERSION_COLUMN_NAME = "Version";
	protected static readonly string DESCRIPTION_COLUMN_NAME = "Description";
	protected static readonly string THREAD_COLUMN_NAME = "Thread";

	/* @DBAnnotatedColumn(REAL_TIME_COLUMN_NAME) */
	static DBObjectColumn REAL_TIME_COLUMN;
	/* @DBAnnotatedColumn(SCHEDULE_COLUMN_NAME) */
	static DBObjectColumn SCHEDULE_COLUMN;
	/* @DBAnnotatedColumn(VERSION_COLUMN_NAME) */
	static DBObjectColumn VERSION_COLUMN;
	/* @DBAnnotatedColumn(DESCRIPTION_COLUMN_NAME) */
	static DBObjectColumn DESCRIPTION_COLUMN;
	/* @DBAnnotatedColumn(THREAD_COLUMN_NAME) */
	static DBObjectColumn THREAD_COLUMN;

	/* @DBAnnotatedField(column = REAL_TIME_COLUMN_NAME) */
	long realTime; // milliseconds
	/* @DBAnnotatedField(column = SCHEDULE_COLUMN_NAME, indexed = true) */
	string scheduleStr = "";
	/* @DBAnnotatedField(column = VERSION_COLUMN_NAME) */
	long version;
	/* @DBAnnotatedField(column = DESCRIPTION_COLUMN_NAME) */
	string description;
	/* @DBAnnotatedField(column = THREAD_COLUMN_NAME) */
	long threadKey = -1;

	public DBTraceTimeManager manager;

	private TraceThread eventThread;
	private TraceSchedule schedule;
	private bool isFork;

	public DBTraceSnapshot(DBTraceTimeManager manager, DBCachedObjectStore<object> store,
			DBRecord record) : base(store, record)
    {
		this.manager = manager;
	}

	/* @Override */
	protected void fresh(bool created)
    {
		if (created) {
			threadKey = -1;
			scheduleStr = "";
			isFork = false;
		}
		else {
			eventThread = manager.threadManager.getThread(threadKey);
			if (!"".equals(scheduleStr)) {
				try {
					schedule = TraceSchedule.parse(scheduleStr, TimeRadix.DEC);
				}
				catch (IllegalArgumentException e) {
					Msg.error(this, "Could not parse schedule: " + schedule, e);
					// Leave as null (or previous value?)
				}
			}
			isFork = computeIsFork();
		}
	}

	protected bool computeIsFork() {
		if (key == long.MinValue) {
			return false;
		}
		if (schedule == null) {
			return false;
		}
		return schedule.getSnap() != key - 1;
	}

	/* @Override */
	public string toString() {
		return string.format(
			"<DBTraceSnapshot key=%d, realTime=%d, schedule='%s', description='%s'>",
			key, realTime, scheduleStr, description);
	}

	protected void set(long realTime, string description) {
		this.realTime = realTime;
		this.description = description;
		update(REAL_TIME_COLUMN, DESCRIPTION_COLUMN);
	}

	/* @Override */
	public Trace getTrace() {
		return manager.trace;
	}

	/* @Override */
	public long getRealTime() {
		using (LockHold hold = LockHold.@lock(manager.@lock.readLock()))
{
			return realTime;
		}
	}

	/* @Override */
	public void setRealTime(long millis) {
		using (LockHold hold = LockHold.@lock(manager.@lock.writeLock()))
{
			this.realTime = millis;
			update(REAL_TIME_COLUMN);
			manager.notifySnapshotChanged(this);
		}
	}

	/* @Override */
	public string getDescription() {
		using (LockHold hold = LockHold.@lock(manager.@lock.readLock()))
{
			return description;
		}
	}

	/* @Override */
	public void setDescription(string description) {
		using (LockHold hold = LockHold.@lock(manager.@lock.writeLock()))
{
			this.description = description;
			update(DESCRIPTION_COLUMN);
			manager.notifySnapshotChanged(this);
		}
	}

	/* @Override */
	public TraceThread getEventThread() {
		using (LockHold hold = LockHold.@lock(manager.@lock.readLock()))
{
			if (eventThread != null) {
				return eventThread;
			}
			// TODO: Can it be something other than root?
			DBTraceObject root = manager.trace.getObjectManager().getRootObject();
			if (root == null) {
				return null;
			}
			if (!root.getSchema().getInterfaces().contains(typeof(TraceEventScope))) {
				return null;
			}
			TraceObjectValue eventAttr =
				root.getAttribute(getKey(), TraceEventScope.KEY_EVENT_THREAD);
			if (eventAttr == null) {
				return null;
			}
			if (!(eventAttr.getValue() is TraceObject eventObj)) {
				return null;
			}
			return eventObj.queryInterface(typeof(TraceThread));
		}
	}

	/* @Override */
	public void setEventThread(TraceThread thread) {
		using (LockHold hold = LockHold.@lock(manager.@lock.writeLock()))
{
			if (thread == null) {
				eventThread = null;
				threadKey = -1;
			}
			else {
				eventThread = manager.threadManager.assertIsMine(thread);
				threadKey = thread.getKey();
			}
			update(THREAD_COLUMN);
			manager.notifySnapshotChanged(this);
		}
	}

	/* @Override */
	public TraceSchedule getSchedule() {
		using (LockHold hold = LockHold.@lock(manager.@lock.readLock()))
{
			return schedule;
		}
	}

	/* @Override */
	public string getScheduleString() {
		using (LockHold hold = LockHold.@lock(manager.@lock.readLock()))
{
			return scheduleStr;
		}
	}

	/* @Override */
	public bool isFork() {
		using (LockHold hold = LockHold.@lock(manager.@lock.readLock()))
{
			return isFork;
		}
	}

	/* @Override */
	public void setSchedule(TraceSchedule schedule) {
		using (LockHold hold = LockHold.@lock(manager.@lock.writeLock()))
{
			this.schedule = schedule;
			this.scheduleStr = schedule == null ? "" : schedule.toString(TimeRadix.DEC);
			this.isFork = computeIsFork();
			update(SCHEDULE_COLUMN);

			DBTraceFork foundFork = manager.forksBySnap.getOne(key);
			if (foundFork != null && !isFork) {
				manager.forkStore.delete(foundFork);
			}
			else if (foundFork == null && isFork) {
				manager.forkStore.create().set(key);
			}

			manager.notifySnapshotChanged(this);
		}
	}

	/* @Override */
	public long getVersion() {
		using (LockHold hold = LockHold.@lock(manager.@lock.readLock()))
{
			return version;
		}
	}

	/* @Override */
	public void setVersion(long version) {
		using (LockHold hold = LockHold.@lock(manager.@lock.writeLock()))
{
			this.version = version;
			update(VERSION_COLUMN);
			manager.notifySnapshotChanged(this);
		}
	}

	/* @Override */
	public bool isSnapOnly(bool whenInconsistent) {
		if (schedule == null && key < 0) {
			return whenInconsistent;
		}
		return schedule == null || schedule.isSnapOnly();
	}

	/* @Override */
	public bool isStale(bool whenInconsistent) {
		if (schedule == null) {
			if (key < 0) {
				return whenInconsistent;
			}
			return false; // A recorded snapshot
		}
		if (schedule.isSnapOnly()) {
			return false;
		}
		return version < manager.trace.getEmulatorCacheVersion();
	}

